package xiaozhi.modules.answerspeech;
import static org.junit.jupiter.api.Assertions.*;
import java.io.*;
import java.nio.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicLong;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.springframework.mock.env.MockEnvironment;
import com.fasterxml.jackson.databind.ObjectMapper;
import liquibase.*;
import liquibase.database.jvm.JdbcConnection;
import liquibase.resource.ClassLoaderResourceAccessor;
import xiaozhi.modules.conversation.*;
import xiaozhi.modules.conversation.ConversationModels.*;
import xiaozhi.modules.externalidentity.*;
import xiaozhi.modules.externalidentity.ExternalModels.*;
import static xiaozhi.modules.answerspeech.AnswerSpeechModels.*;

/** Real MySQL identity/renewal, private WAV bytes and interleaving IO; synthesis bytes are explicit fixtures, not provider acceptance. */
@EnabledIfEnvironmentVariable(named="ANSWER_SPEECH_TEST_JDBC_URL",matches=".+")
class AnswerSpeechPersistenceTest {
    static JdbcTemplate db;static DataSourceTransactionManager manager;static ObjectMapper json;static Path objects;static AtomicLong users=new AtomicLong(1200);
    AnswerSpeechService service;ConversationService conversations;MockEnvironment env;ExternalSettings settings;ExternalIdentityService identity;
    long owner;String conversation,message;byte[] signing;String bearer;Principal principal;
    @BeforeAll static void database()throws Exception{
        String url=System.getenv("ANSWER_SPEECH_TEST_JDBC_URL");if(!url.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/xiaozhi_answer_speech_test_[a-z0-9_]+(\\?.*)?"))throw new IllegalArgumentException("A NEW isolated answer speech schema is required");
        var source=new DriverManagerDataSource(url,"root",System.getenv("ANSWER_SPEECH_TEST_DB_PASSWORD"));db=new JdbcTemplate(source);manager=new DataSourceTransactionManager(source);json=new xiaozhi.modules.security.config.WebMvcConfig().jackson2HttpMessageConverter().getObjectMapper();assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE()",Long.class),"Never reset a preexisting schema");
        db.execute("CREATE TABLE sys_user(id BIGINT PRIMARY KEY,status TINYINT NOT NULL,super_admin TINYINT NOT NULL DEFAULT 0,username VARCHAR(80) UNIQUE,password VARCHAR(100),create_date DATETIME(3))");db.execute("CREATE TABLE ai_agent(id VARCHAR(32) PRIMARY KEY,user_id BIGINT)");
        for(String name:List.of("conversation","support","ai-execution","external-identity","answer-speech"))try(var connection=source.getConnection();var migration=new Liquibase("db/changelog/"+name+".changelog.yaml",new ClassLoaderResourceAccessor(),new JdbcConnection(connection))){migration.update(new Contexts());migration.update(new Contexts());}
        assertEquals(7,db.queryForObject("SELECT COUNT(*) FROM DATABASECHANGELOG",Long.class));objects=Files.createTempDirectory("answer-speech-retained-");
    }
    @BeforeEach void fixture(){owner=users.incrementAndGet();db.update("INSERT INTO sys_user(id,status,super_admin,username) VALUES(?,1,0,?)",owner,"speech-local-"+owner);env=new MockEnvironment().withProperty("features.answer-speech-enabled","true").withProperty("answer-speech.storage-root",objects.toString());service=new AnswerSpeechService(db,json,manager,env);conversations=new ConversationService(new ConversationDao(db),json,manager);
        signing=new byte[32];new java.security.SecureRandom().nextBytes(signing);settings=new ExternalSettings();settings.setEnabled(true);settings.setRenewalEnabled(true);settings.setTokenSeconds(300);settings.setKeysJson("{\"xiaozhi-speech-key\":{\"issuer\":\"xiaozhi-speech-test\",\"secret_b64\":\""+Base64.getEncoder().encodeToString(signing)+"\"}}");identity=new ExternalIdentityService(db,json,manager,settings);service.setIdentity(identity);
    }
    @AfterEach void retainFixtures(){env.setProperty("features.answer-speech-enabled","true");if(conversation!=null)for(String id:db.query("SELECT id FROM ai_answer_speech_job WHERE owner_user_id=? AND status IN ('queued','synthesizing')",(r,n)->r.getString(1),owner))service.cancel(owner,conversation,id,principal);}
    void connect(boolean external)throws Exception{if(external){bearer=login();principal=identity.authenticate(bearer);owner=principal.userId();}conversation=conversations.create(owner,new CreateConversation("Speech fixture",null)).id();message=assistant("Published answer fixture");}
    String assistant(String text)throws Exception{String id=uuid();long seq=db.queryForObject("SELECT last_seq FROM ai_conversation WHERE id=?",Long.class,conversation)+1;db.update("INSERT INTO ai_message(id,conversation_id,seq,client_message_id,sender_type,sender_id,parts_json,request_hash,status) VALUES(?,?,?,?, 'assistant','ai',?,?,'completed')",id,conversation,seq,"fixture:"+id,json.writeValueAsString(List.of(Map.of("type","text","text",text))),AnswerSpeechService.hash(id));db.update("UPDATE ai_conversation SET last_seq=? WHERE id=?",seq,conversation);return id;}
    String login()throws Exception{var node=json.createObjectNode().put("external_subject","speech-"+users.get()).put("source_session_id","source-session").put("source_expires_at",Long.toString(Instant.now().getEpochSecond()+3600)).put("display_name","Speech fixture");node.putObject("tenant").put("type","company").put("id","1");var scope=node.putObject("scope");scope.putArray("project_ids");scope.putArray("device_ids");byte[] raw=json.writeValueAsBytes(node);var ticket=identity.issue(identity.verify(ExternalIdentityService.ISSUE,raw,signed(ExternalIdentityService.ISSUE,raw)),raw);return identity.exchange(ticket.ticket()).token();}
    Map<String,List<String>> signed(String path,byte[] raw){String timestamp=Long.toString(Instant.now().getEpochSecond()),nonce=uuid();return Map.of("x-external-key-id",List.of("xiaozhi-speech-key"),"x-external-timestamp",List.of(timestamp),"x-external-nonce",List.of(nonce),"x-external-signature",List.of(ExternalIdentityService.signature(signing,path,timestamp,nonce,raw)));}
    Task dispatch(){var job=service.create(owner,conversation,message,new Create(uuid()),principal);var task=service.claim(new Claim("speech-fixture"));assertEquals(job.id(),task.jobId());return task;}
    Fence fence(Task task){return new Fence(task.leaseToken(),task.attempt(),task.messageVersion(),task.textSha256());}
    UsageReport usage(Task task,Long characters){return new UsageReport(task.leaseToken(),task.attempt(),task.messageVersion(),task.textSha256(),characters==null?null:new Usage(characters),null);}
    Finish finish(Task task,String sha,Long characters){return new Finish(task.leaseToken(),task.attempt(),task.messageVersion(),task.textSha256(),sha,characters==null?null:new Usage(characters),null);}
    static byte[] wav(){byte[] bytes=new byte[48044];ByteBuffer b=ByteBuffer.wrap(bytes).order(ByteOrder.LITTLE_ENDIAN);b.put("RIFF".getBytes()).putInt(bytes.length-8).put("WAVEfmt ".getBytes()).putInt(16).putShort((short)1).putShort((short)1).putInt(24000).putInt(48000).putShort((short)2).putShort((short)16).put("data".getBytes()).putInt(bytes.length-44);return bytes;}
    String upload(Task task)throws Exception{byte[] bytes=wav();String sha=AnswerSpeechService.hash(bytes);var uploaded=service.upload(task.jobId(),fence(task),sha,new ByteArrayInputStream(bytes),bytes.length);assertEquals(1000,uploaded.durationMs());return sha;}
    @Test void onlyPublishedAssistantExactVersionAndRequestIdAreAccepted()throws Exception{connect(false);var job=service.create(owner,conversation,message,new Create("same-request"),null);assertEquals(job.id(),service.create(owner,conversation,message,new Create("same-request"),null).id());String other=assistant("Second answer");assertEquals(409,assertThrows(ConversationProblem.class,()->service.create(owner,conversation,other,new Create("same-request"),null)).status());assertThrows(ConversationProblem.class,()->service.get(owner+100,conversation,job.id(),null));db.update("UPDATE ai_message SET status='running' WHERE id=?",message);assertThrows(ConversationProblem.class,()->service.create(owner,conversation,message,new Create(uuid()),null));db.update("UPDATE ai_message SET status='completed',sender_type='user' WHERE id=?",message);assertThrows(ConversationProblem.class,()->service.create(owner,conversation,message,new Create(uuid()),null));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_job WHERE owner_user_id=?",owner));}
    @Test void wavDigestCompletePrivateReadFreshGrantAndUnknownUsageRemainNull()throws Exception{connect(false);Task task=dispatch();assertEquals(AnswerSpeechService.hash(task.text()),task.textSha256());assertNotEquals(task.messageVersion(),task.textSha256());String sha=upload(task);assertEquals(sha,upload(task));Job job=service.complete(task.jobId(),finish(task,sha,null));assertEquals("completed",job.status());assertEquals(job.id(),service.complete(task.jobId(),finish(task,sha,null)).id());assertEquals("available",job.resultAccess());assertNotNull(job.playbackAuthorizedUntil());assertTrue(job.playbackAuthorizedUntil().isBefore(Instant.now().plusSeconds(6)));try(var content=service.audio(owner,conversation,task.jobId(),null)){assertArrayEquals(wav(),content.input().readAllBytes());content.guard().run();}assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_usage WHERE job_id=? AND characters IS NULL AND provider_request_id IS NULL",task.jobId()));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_audit WHERE job_id=? AND state='completed'",task.jobId()));if(Files.getFileStore(objects).supportsFileAttributeView("posix")){Path file=objects.resolve(db.queryForObject("SELECT audio_path FROM ai_answer_speech_job WHERE id=?",String.class,task.jobId()));assertEquals(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"),Files.getPosixFilePermissions(file));assertEquals(java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"),Files.getPosixFilePermissions(objects));}}
    @Test void cancelDuringBodyReadDoesNotBlockOnSqlAndCannotPublishArtifact()throws Exception{connect(false);Task task=dispatch();byte[] bytes=wav();CountDownLatch reading=new CountDownLatch(1),release=new CountDownLatch(1);var executor=Executors.newSingleThreadExecutor();InputStream slow=new ByteArrayInputStream(bytes){@Override public synchronized byte[] readNBytes(int max){reading.countDown();try{assertTrue(release.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new RuntimeException(e);}return bytes;}};try{var upload=executor.submit(()->service.upload(task.jobId(),fence(task),AnswerSpeechService.hash(bytes),slow,bytes.length));assertTrue(reading.await(5,TimeUnit.SECONDS));assertEquals("canceled",service.cancel(owner,conversation,task.jobId(),null).status());release.countDown();assertInstanceOf(ConversationProblem.class,assertThrows(ExecutionException.class,()->upload.get(5,TimeUnit.SECONDS)).getCause());assertEquals(0,count("SELECT COUNT(*) FROM ai_answer_speech_job WHERE id=? AND audio_sha256 IS NOT NULL",task.jobId()));service.reportUsage(task.jobId(),usage(task,23L));assertEquals(23,db.queryForObject("SELECT characters FROM ai_answer_speech_usage WHERE job_id=?",Long.class,task.jobId()));}finally{release.countDown();executor.shutdownNow();}}
    @Test void exactBearerRenewalAllowedReplacementRestrictedAndSourceRevocationStopsChunk()throws Exception{connect(true);Task task=dispatch();String sha=upload(task);db.update("UPDATE external_access_token SET expires_at=DATE_ADD(CURRENT_TIMESTAMP(3),INTERVAL 40 SECOND) WHERE id=?",principal.tokenId());var body=json.createObjectNode().put("external_subject",principal.subject()).put("source_session_id","source-session").put("token_id",Long.toString(principal.tokenId())).put("requested_lifetime_seconds",120);body.set("tenant",json.valueToTree(principal.tenant()));body.set("scope",json.valueToTree(principal.scope()));byte[] raw=json.writeValueAsBytes(body);identity.renew(ExternalIdentityService.RENEW,raw,signed(ExternalIdentityService.RENEW,raw));Principal renewed=identity.authenticate(bearer);assertTrue(ExternalIdentityService.sameBinding(principal,renewed));service.complete(task.jobId(),finish(task,sha,23L));assertNotNull(service.get(owner,conversation,task.jobId(),renewed).playbackAuthorizedUntil());Principal replacement=identity.authenticate(login());assertEquals("restricted",service.get(owner,conversation,task.jobId(),replacement).resultAccess());assertNull(service.get(owner,conversation,task.jobId(),replacement).playbackAuthorizedUntil());assertThrows(ConversationProblem.class,()->service.audio(owner,conversation,task.jobId(),replacement));try(var stream=service.audio(owner,conversation,task.jobId(),renewed)){db.update("UPDATE external_source_session SET revoked_at=CURRENT_TIMESTAMP(3) WHERE id=?",principal.sourceId());assertThrows(ConversationProblem.class,stream.guard()::run);}assertEquals("restricted",service.get(owner,conversation,task.jobId(),renewed).resultAccess());assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_usage WHERE job_id=?",task.jobId()));}
    @Test void expiredDispatchIsFailedWithoutRetryAndHistoricalUsageDoesNotReviveIt()throws Exception{connect(false);Task task=dispatch();db.update("UPDATE ai_answer_speech_attempt SET lease_expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE job_id=?",task.jobId());assertNull(service.claim(new Claim("other-worker")));assertEquals("failed",service.get(owner,conversation,task.jobId(),null).status());assertThrows(ConversationProblem.class,()->service.heartbeat(task.jobId(),fence(task)));service.reportUsage(task.jobId(),usage(task,23L));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_attempt WHERE job_id=?",task.jobId()));assertEquals("failed",service.get(owner,conversation,task.jobId(),null).status());assertThrows(ConversationProblem.class,()->service.reportUsage(task.jobId(),usage(task,24L)));}
    @Test void perOwnerActiveUniquenessHoldsUnderConcurrentRequests()throws Exception{connect(false);var pool=Executors.newFixedThreadPool(2);CountDownLatch start=new CountDownLatch(1);Callable<Object> create=()->{start.await();try{return service.create(owner,conversation,message,new Create(uuid()),null);}catch(ConversationProblem denied){return denied;}};try{var a=pool.submit(create);var b=pool.submit(create);start.countDown();List<Object> results=List.of(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));assertEquals(1,results.stream().filter(Job.class::isInstance).count());assertEquals(1,results.stream().filter(ConversationProblem.class::isInstance).count());assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_job WHERE owner_user_id=?",owner));}finally{pool.shutdownNow();}}
    @Test void changedMessageRejectsLateCompletionButKeepsActualFeeAndMetadata()throws Exception{connect(false);Task task=dispatch();String sha=upload(task);db.update("UPDATE ai_message SET parts_json='[{\"type\":\"text\",\"text\":\"changed\"}]' WHERE id=?",message);assertThrows(ConversationProblem.class,()->service.complete(task.jobId(),finish(task,sha,23L)));assertEquals(23,db.queryForObject("SELECT characters FROM ai_answer_speech_usage WHERE job_id=?",Long.class,task.jobId()));assertEquals("restricted",service.get(owner,conversation,task.jobId(),null).resultAccess());assertNotEquals("completed",service.get(owner,conversation,task.jobId(),null).status());}
    @Test void forgedAudioHeadersAndNonPcmBytesAreRejectedBeforeArtifactCommit()throws Exception{connect(false);Task task=dispatch();byte[] bytes=wav();assertThrows(ConversationProblem.class,()->service.upload(task.jobId(),fence(task),"0".repeat(64),new ByteArrayInputStream(bytes),bytes.length));bytes[24]=1;assertThrows(ConversationProblem.class,()->service.upload(task.jobId(),fence(task),AnswerSpeechService.hash(bytes),new ByteArrayInputStream(bytes),bytes.length));assertEquals(0,count("SELECT COUNT(*) FROM ai_answer_speech_job WHERE id=? AND audio_path IS NOT NULL",task.jobId()));var invalid=new Fence("0".repeat(64),task.attempt(),task.messageVersion(),task.textSha256());assertThrows(ConversationProblem.class,()->service.heartbeat(task.jobId(),invalid));}
    @Test void disabledFeatureRejectsFreshActionsButAllowsExactHistoricalFeeOnly()throws Exception{connect(false);Task task=dispatch();env.setProperty("features.answer-speech-enabled","false");assertThrows(ConversationProblem.class,()->service.heartbeat(task.jobId(),fence(task)));assertThrows(ConversationProblem.class,()->service.create(owner,conversation,message,new Create(uuid()),null));service.reportUsage(task.jobId(),usage(task,23L));assertEquals(23,db.queryForObject("SELECT characters FROM ai_answer_speech_usage WHERE job_id=?",Long.class,task.jobId()));}
    static String uuid(){return UUID.randomUUID().toString().replace("-","");}long count(String sql,Object...args){return db.queryForObject(sql,Long.class,args);}
    @Test void ownerPollingTerminatesExpiredWorkerLeaseWithoutAnotherWorkerClaim()throws Exception{connect(false);Task task=dispatch();db.update("UPDATE ai_answer_speech_attempt SET lease_expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE job_id=?",task.jobId());assertEquals("failed",service.get(owner,conversation,task.jobId(),null).status(),"A crashed worker must not leave the UI synthesizing forever");assertEquals("SPEECH_PROVIDER_TIMEOUT",service.get(owner,conversation,task.jobId(),null).errorCode());service.reportUsage(task.jobId(),usage(task,23L));assertEquals(23,db.queryForObject("SELECT characters FROM ai_answer_speech_usage WHERE job_id=?",Long.class,task.jobId()));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_audit WHERE job_id=? AND state='failed'",task.jobId()));}
    @Test void queuedJobDeadlineIsVisibleEvenWhenNoWorkerEverClaimsIt()throws Exception{connect(false);Job job=service.create(owner,conversation,message,new Create(uuid()),null);db.update("UPDATE ai_answer_speech_job SET created_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 6 MINUTE) WHERE id=?",job.id());assertEquals("failed",service.get(owner,conversation,job.id(),null).status());assertEquals(0,count("SELECT COUNT(*) FROM ai_answer_speech_attempt WHERE job_id=?",job.id()));assertEquals(0,count("SELECT COUNT(*) FROM ai_answer_speech_usage WHERE job_id=?",job.id()));}
    @Test void regularHeartbeatsCannotExtendAbsoluteSynthesisDeadline()throws Exception{connect(false);Task task=dispatch();db.update("UPDATE ai_answer_speech_attempt SET dispatched_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 181 SECOND),lease_expires_at=DATE_ADD(CURRENT_TIMESTAMP(3),INTERVAL 45 SECOND) WHERE job_id=?",task.jobId());assertThrows(ConversationProblem.class,()->service.heartbeat(task.jobId(),fence(task)));assertEquals("failed",service.get(owner,conversation,task.jobId(),null).status());service.reportUsage(task.jobId(),usage(task,null));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_usage WHERE job_id=? AND characters IS NULL",task.jobId()));assertNull(service.claim(new Claim("replacement")));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_attempt WHERE job_id=?",task.jobId()));}

    @Test void backgroundMaintenanceReleasesAnUnobservedExpiredJobWithoutSynthesisRetry()throws Exception{connect(false);Task task=dispatch();db.update("UPDATE ai_answer_speech_attempt SET lease_expires_at=DATE_SUB(CURRENT_TIMESTAMP(3),INTERVAL 1 SECOND) WHERE job_id=?",task.jobId());new AnswerSpeechMaintenance(service).tick();new AnswerSpeechMaintenance(service).tick();assertEquals("failed",db.queryForObject("SELECT status FROM ai_answer_speech_job WHERE id=?",String.class,task.jobId()));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_audit WHERE job_id=? AND state='failed'",task.jobId()));assertEquals(1,count("SELECT COUNT(*) FROM ai_answer_speech_attempt WHERE job_id=?",task.jobId()));assertEquals(0,count("SELECT COUNT(*) FROM ai_answer_speech_usage WHERE job_id=?",task.jobId()));var next=service.create(owner,conversation,message,new Create(uuid()),null);assertEquals("queued",next.status());service.reportUsage(task.jobId(),usage(task,23L));assertEquals(23,db.queryForObject("SELECT characters FROM ai_answer_speech_usage WHERE job_id=?",Long.class,task.jobId()));assertEquals("queued",service.get(owner,conversation,next.id(),null).status());}

}
